mapper.update:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modStoreStatus
SQL 명: 가게 영업 상태 변경
*/
UPDATE tb_store
   SET status = #{status}
 WHERE id = #{storeId}

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modStoreWaitTime
SQL 명: 가게 대기시간(조리 예상 시간) 변경
*/
UPDATE tb_store
   SET delivery_time = #{minutes}
 WHERE id = #{storeId}

mapper.select:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.getOwnerOrderList
SQL 명: 사장님 가게 주문 목록
*/

 WHERE o.store_id = #{storeId}

 ORDER BY o.created_datetime DESC
 LIMIT #{limit} OFFSET #{offset}

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.getOwnerOrder
SQL 명: 사장님 가게 주문 단건
*/

 WHERE o.store_id = #{storeId}
   AND o.order_id = #{orderId}

mapper.update:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modOrderStatus
SQL 명: 사장님 주문 단계 변경
*/
UPDATE tb_order
   SET status           = #{toStatus}
     , updated_datetime = NOW()
 WHERE store_id = #{storeId}
   AND order_id = #{orderId}
   AND status   = #{fromStatus}

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modMenuSoldOut
SQL 명: 메뉴 품절 여부 변경
*/
UPDATE tb_menus
   SET is_sold_out = #{isSoldOut}
 WHERE id = #{menuId}
   AND store_id = #{storeId}
   AND is_active = 1
